def count_cycle(iterable, n=None):
    """Cycle through the items from *iterable* up to *n* times, yielding
    the number of completed cycles along with each item. If *n* is omitted the
    process repeats indefinitely.

    >>> list(count_cycle('AB', 3))
    [(0, 'A'), (0, 'B'), (1, 'A'), (1, 'B'), (2, 'A'), (2, 'B')]

    """
    if n is not None:
        return product(range(n), iterable)
    seq = tuple(iterable)
    if not seq:
        return iter(())
    return zip(repeat_each(count(), len(seq)), cycle(seq))

def test_result_index(self):
    def stringify(*args, **kwargs):
        self.assertEqual(args[0], 'arg_0')
        iterable = args[1]
        self.assertEqual(args[2], 'arg_2')
        self.assertEqual(kwargs['kwarg_1'], 'kwarg_1')
        return map(str, iterable)

    stringifier = mi.make_decorator(stringify, result_index=1)

    @stringifier('arg_0', 'arg_2', kwarg_1='kwarg_1')
    def user_function(n):
        return count(n)

    it = user_function(1)
    actual = mi.take(5, it)
    expected = ['1', '2', '3', '4', '5']
    self.assertEqual(actual, expected)

def test_noninteger_window(self):
    for function in self.functions:
        for maxlen in (2.5, 2.0, float('nan'), float('inf')):
            with self.subTest(function=function, maxlen=maxlen):
                with self.assertRaises(TypeError):
                    list(function([1, 2, 3, 4], maxlen=maxlen))

